-- MySQL schema for Namecheap cPanel. Import with phpMyAdmin after creating the database/user.
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(191) NOT NULL UNIQUE,full_name VARCHAR(255) NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','supervisor','team_leader','agent') NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,deactivated_at DATETIME NULL);
CREATE TABLE teams (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(191) NOT NULL UNIQUE,leader_user_id BIGINT UNSIGNED NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,deactivated_at DATETIME NULL,FOREIGN KEY(leader_user_id) REFERENCES users(id));
CREATE TABLE agents (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,employee_id VARCHAR(191) NOT NULL UNIQUE,full_name VARCHAR(255) NOT NULL,user_id BIGINT UNSIGNED NULL UNIQUE,phone VARCHAR(100),status ENUM('active','suspended','left_organization') NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,joined_at DATE,deactivated_at DATETIME NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE agent_team_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,agent_id BIGINT UNSIGNED NOT NULL,team_id BIGINT UNSIGNED NOT NULL,team_leader_id BIGINT UNSIGNED NULL,started_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,ended_at DATETIME NULL,changed_by BIGINT UNSIGNED NOT NULL,reason TEXT,FOREIGN KEY(agent_id) REFERENCES agents(id),FOREIGN KEY(team_id) REFERENCES teams(id),FOREIGN KEY(team_leader_id) REFERENCES users(id),FOREIGN KEY(changed_by) REFERENCES users(id),INDEX(agent_id,ended_at));
CREATE TABLE sim_cards (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sim_number VARCHAR(191) NOT NULL UNIQUE,msisdn VARCHAR(191) UNIQUE,iccid VARCHAR(191) UNIQUE,provider VARCHAR(191) NOT NULL,sim_type VARCHAR(100),current_status VARCHAR(50) NOT NULL DEFAULT 'available',current_balance DECIMAL(14,2),added_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,status_reason TEXT,notes TEXT,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_by BIGINT UNSIGNED NOT NULL,FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE sim_assignments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sim_id BIGINT UNSIGNED NOT NULL,agent_id BIGINT UNSIGNED NOT NULL,team_id BIGINT UNSIGNED NULL,assigned_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,removed_at DATETIME NULL,assigned_by BIGINT UNSIGNED NOT NULL,removed_by BIGINT UNSIGNED NULL,reason TEXT,FOREIGN KEY(sim_id) REFERENCES sim_cards(id),FOREIGN KEY(agent_id) REFERENCES agents(id),FOREIGN KEY(team_id) REFERENCES teams(id),FOREIGN KEY(assigned_by) REFERENCES users(id),FOREIGN KEY(removed_by) REFERENCES users(id),INDEX(sim_id,removed_at));
CREATE TABLE sim_status_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sim_id BIGINT UNSIGNED NOT NULL,previous_status VARCHAR(50),new_status VARCHAR(50) NOT NULL,occurred_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,changed_by BIGINT UNSIGNED NOT NULL,notes TEXT,FOREIGN KEY(sim_id) REFERENCES sim_cards(id),FOREIGN KEY(changed_by) REFERENCES users(id));
CREATE TABLE weekly_sim_usage (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sim_id BIGINT UNSIGNED NOT NULL,agent_id BIGINT UNSIGNED NULL,team_id BIGINT UNSIGNED NULL,week_start DATE NOT NULL,week_end DATE NOT NULL,airtime_purchased DECIMAL(14,2) NOT NULL DEFAULT 0,sms_bundle_purchased DECIMAL(14,2) NOT NULL DEFAULT 0,calling_minutes_purchased DECIMAL(14,2) NOT NULL DEFAULT 0,data_bundle_purchased DECIMAL(14,2) NOT NULL DEFAULT 0,data_used_mb DECIMAL(14,2),sms_used DECIMAL(14,2),notes TEXT,submitted_by BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(sim_id,week_start),FOREIGN KEY(sim_id) REFERENCES sim_cards(id),FOREIGN KEY(submitted_by) REFERENCES users(id));
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,occurred_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,actor_id BIGINT UNSIGNED NULL,action VARCHAR(255) NOT NULL,object_type VARCHAR(100) NOT NULL,object_id BIGINT UNSIGNED NULL,new_value JSON,FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE equipment_damage_reports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,agent_id BIGINT UNSIGNED NOT NULL,item VARCHAR(255) NOT NULL,condition VARCHAR(100) NOT NULL,damaged_on DATE NOT NULL,reported_on DATE NOT NULL,notes TEXT NOT NULL,reported_by BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(agent_id) REFERENCES agents(id),FOREIGN KEY(reported_by) REFERENCES users(id));
